  KEY `cid_inout_id` (`inout_id`),
  KEY `cid_community_id` (`community_id`),
  KEY `cid_car_num` (`car_num`),
  KEY `cid_pa_id` (`pa_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

