-- ----------------------------
-- Table structure for charge_peak_alley_price
-- ----------------------------
DROP TABLE IF EXISTS `charge_peak_alley_price`;
CREATE TABLE `charge_peak_alley_price` (
  `cpa_id` varchar(30) NOT NULL COMMENT '规则ID',
  `rule_id` varchar(30) NOT NULL COMMENT '规则ID',
  `type` varchar(12) NOT NULL COMMENT '价格类型\r\n00，\r\n尖费电费费率 BIN码 4 精确到五位小数 \r\n尖服务费费率 BIN码 4 精确到五位小数 \r\n01\r\n峰电费费率 BIN码 4 精确到五位小数 \r\n峰服务费费率 BIN码 4 精确到五位小数 \r\n02\r\n平电费费率 BIN码 4 精确到五位小数 \r\n平服务费费率 BIN码 4 精确到五位小数 \r\n03\r\n谷电费费率 BIN码 4 精确到五位小数 \r\n谷服务费费率 BIN码 4 精确到五位小数 ',
  `price` decimal(10,2) NOT NULL COMMENT '电费费率',
  `service_price` decimal(10,2) NOT NULL COMMENT '服务费费率',
  `community_id` varchar(30) DEFAULT NULL COMMENT '小区ID',
  `remark` varchar(512) DEFAULT NULL COMMENT '备注',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `status_cd` varchar(2) NOT NULL DEFAULT '0' COMMENT '数据状态，详细参考c_status表，S 保存，0, 在用 1失效',
  PRIMARY KEY (`cpa_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- ----------------------------
-- Table structure for charge_process_analysis
-- ----------------------------
DROP TABLE IF EXISTS `charge_process_analysis`;
CREATE TABLE `charge_process_analysis` (
  `cpa_id` varchar(30) NOT NULL COMMENT '规则ID',
  `order_id` varchar(50) DEFAULT NULL COMMENT '订单ID',
  `machine_id` varchar(30) DEFAULT NULL COMMENT '设备ID',
  `community_id` varchar(30) NOT NULL COMMENT '小区ID',
  `pile_num` varchar(16) DEFAULT NULL COMMENT '桩编号',
  `gun_num` varchar(2) DEFAULT NULL COMMENT '枪编号',
  `status` varchar(2) DEFAULT NULL COMMENT '状态：离线\r\n0x00：离线 \r\n0x01：故障  \r\n0x02：空闲  \r\n0x03：充电 \r\n需做到变位上送 ',
  `back_in_place` varchar(2) DEFAULT NULL COMMENT '枪是否归位\r\n0x00 否 0x01 是 0x02未知 \r\n（无法检测到枪是否插回枪座即未知）',
  `inserted_gun` varchar(2) DEFAULT NULL COMMENT '是否插枪 \r\n0x00否 0x01是 \r\n需做到变位上送 ',
  `output_voltage` varchar(8) DEFAULT NULL COMMENT '输出电压',
  `output_current` varchar(8) DEFAULT NULL COMMENT '输出电流',
  `gun_line_tem` varchar(8) DEFAULT NULL COMMENT '枪线温度',
  `gun_code` varchar(16) DEFAULT NULL COMMENT '枪线编码',
  `soc` varchar(4) DEFAULT NULL COMMENT 'SOC',
  `batterypack_max_tem` varchar(4) DEFAULT NULL COMMENT '电池组最高温度',
  `accumulated_charging_time` varchar(4) DEFAULT NULL COMMENT '累计充电时间单位：min；待机置零',
  `remaining_time` varchar(4) DEFAULT NULL COMMENT '剩余时间单位：min；待机置零、交流桩置\r\n零 ',
  `charging_degree` varchar(8) DEFAULT NULL COMMENT '充电度数 精确到小数点后四位；待机置零',
  `calculated_charging_degree` varchar(8) DEFAULT NULL COMMENT '计损充电度数\r\n精确到小数点后四位；待机置零 \r\n未设置计损比例时等于充电度数',
  `recharge_amount` varchar(8) DEFAULT NULL COMMENT '已充金额\r\n精确到小数点后四位；待机置零 \r\n（电费+服务费）*计损充电度数',
  `hardware_failure` varchar(4) DEFAULT NULL COMMENT '硬件故障\r\nBit位表示（0否1是），低位到高位顺序 \r\nBit1：急停按钮动作故障； \r\nBit2：无可用整流模块； \r\nBit3：出风口温度过高； \r\nBit4：交流防雷故障； \r\nBit5：交直流模块 DC20 通信中断； \r\nBit6：绝缘检测模块 FC08 通信中断； \r\nBit7：电度表通信中断； \r\nBit8：读卡器通信中断； \r\nBit9：RC10 通信中断； \r\nBit10：风扇调速板故障； \r\nBit11：直流熔断器故障； \r\nBit12：高压接触器故障； \r\nBit13：门打开；',
  `status_cd` varchar(2) NOT NULL DEFAULT '0' COMMENT '数据状态，详细参考c_status表，S 保存，0, 在用 1失效',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `remark` varchar(512) DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`cpa_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='充电过程解析0x13';

-- ----------------------------
-- Records of charge_process_analysis
-- ----------------------------

