-- ----------------------------
-- Table structure for event_object
-- ----------------------------
DROP TABLE IF EXISTS `event_object`;
CREATE TABLE `event_object` (
  `eo_id` varchar(30) NOT NULL COMMENT '规则ID',
  `rule_id` varchar(30) NOT NULL COMMENT '规则ID',
  `obj_type` varchar(12) NOT NULL COMMENT '对象类型 1001 门禁 2002 道闸 3003 充电桩 4004 智能电表',
  `object_id` varchar(30) NOT NULL COMMENT '对象ID',
  `object_name` varchar(30) NOT NULL COMMENT '对象名称',
  `community_id` varchar(30) NOT NULL COMMENT '小区ID',
  `state` varchar(12) NOT NULL DEFAULT 'ON' COMMENT '状态 ON 生效 OFF 失效',
  `remark` varchar(512) DEFAULT NULL COMMENT '备注',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `status_cd` varchar(2) NOT NULL DEFAULT '0' COMMENT '数据状态',
  PRIMARY KEY (`eo_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='事件对象';

-- ----------------------------
-- Records of event_object
-- ----------------------------

-- ----------------------------
-- Table structure for event_pool
-- ----------------------------
DROP TABLE IF EXISTS `event_pool`;
CREATE TABLE `event_pool` (
  `event_id` varchar(30) NOT NULL COMMENT '事件ID',
  `rule_id` varchar(30) NOT NULL COMMENT '规则ID',
  `event_type` varchar(12) NOT NULL COMMENT '事件类型，1001 设备离线 2002 温度过高 3003 未知异常',
  `event_msg` varchar(512) NOT NULL COMMENT '事件描述',
  `obj_type` varchar(12) NOT NULL COMMENT '对象类型 1001 门禁 2002 道闸 3003 充电桩 4004 智能电表',
  `object_id` varchar(30) NOT NULL COMMENT '对象ID',
  `object_name` varchar(30) NOT NULL COMMENT '对象名称',
  `from_type` varchar(12) NOT NULL COMMENT '来自 PERSON 人员创建 SYSTEM 平台创建',
  `from_name` varchar(64) NOT NULL COMMENT '来自说明 PERSON 是人员名称 SYSTEM时平台名称',
  `community_id` varchar(30) NOT NULL COMMENT '小区ID',
  `state` varchar(12) NOT NULL DEFAULT 'W' COMMENT '状态 W 待处理 NC 正常处理完成 TC 超时处理完成 D 处理中',
  `remark` varchar(512) DEFAULT NULL COMMENT '备注',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `status_cd` varchar(2) NOT NULL DEFAULT '0' COMMENT '数据状态',
  PRIMARY KEY (`event_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='事件';

-- ----------------------------
-- Records of event_pool
-- ----------------------------

-- ----------------------------
-- Table structure for event_pool_staff
-- ----------------------------
DROP TABLE IF EXISTS `event_pool_staff`;
CREATE TABLE `event_pool_staff` (
  `eps_id` varchar(30) NOT NULL COMMENT '主键ID',
  `event_id` varchar(30) NOT NULL COMMENT '事件ID',
  `staff_id` varchar(30) NOT NULL COMMENT '处理员工',
  `staff_name` varchar(64) NOT NULL COMMENT '处理员工',
  `event_reason` varchar(512) DEFAULT NULL COMMENT '事故原因',
  `event_result` varchar(512) DEFAULT NULL COMMENT '处理方案',
  `event_hours` int(11) DEFAULT '0' COMMENT '处理时长',
  `community_id` varchar(30) NOT NULL COMMENT '小区ID',
  `state` varchar(12) NOT NULL DEFAULT 'W' COMMENT '状态 W 待处理 NC 正常处理完成 TC 超时处理完成 D 处理中',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `status_cd` varchar(2) NOT NULL DEFAULT '0' COMMENT '数据状态',
  PRIMARY KEY (`eps_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='事件处理';

-- ----------------------------
-- Records of event_pool_staff
-- ----------------------------

