-- Table structure for event_template_param_key
-- ----------------------------
DROP TABLE IF EXISTS `event_template_param_key`;
CREATE TABLE `event_template_param_key` (
  `key_id` varchar(30) NOT NULL COMMENT '编号',
  `event_way` varchar(30) NOT NULL COMMENT '通知方式，SMS-ALI 阿里云短信 DINGDING 钉钉群通知 WECHAT 企业微信群通知',
  `spec_name` varchar(30) NOT NULL COMMENT '参数规格名称',
  `spec_cd` varchar(12) NOT NULL COMMENT '参数规格',
  `remark` varchar(512) DEFAULT NULL COMMENT '备注',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `status_cd` varchar(2) NOT NULL DEFAULT '0' COMMENT '数据状态',
  PRIMARY KEY (`key_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='通知模板参数规格';

