  `attr_id` varchar(64) NOT NULL COMMENT '主键',
  `hm_id` varchar(64) NOT NULL COMMENT '厂商ID',
  `spec_cd` varchar(12) NOT NULL COMMENT '规格 95001 是topic',
  `value` varchar(200) NOT NULL COMMENT '规格值',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `status_cd` varchar(2) NOT NULL DEFAULT '0' COMMENT '数据状态，详细参考c_status表，0在用，1失效',
  PRIMARY KEY (`attr_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

