  `fee_config_id` varchar(30) DEFAULT NULL COMMENT '费用项ID,充值模式时 公式选 用量乘以单价 抄表模式 上期读数-本期读数乘以单价',
  `fee_config_name` varchar(64) DEFAULT NULL COMMENT '费用项名称',
