  `parking_type` varchar(3) NOT NULL DEFAULT '1' COMMENT '1：普通车位  2：子母车位  3：豪华车位',
  `pr_id` varchar(30) DEFAULT NULL COMMENT '区域ID',
  `monitor_id` varchar(30) DEFAULT NULL COMMENT '监控ID',
