  `community_id` varchar(30) NOT NULL COMMENT '小区ID',
  `open_id` varchar(64) NOT NULL COMMENT 'openId',
  `qrcode` varchar(128) NOT NULL COMMENT '通信码',
  `qrcode_time` datetime NOT NULL COMMENT '通信码刷新时间',
