  `state` varchar(12) NOT NULL DEFAULT 'ON' COMMENT '状态 W 待审核，F 审核失败 C 审核完成',
  `remark` varchar(512) DEFAULT NULL COMMENT '审核说明',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
