-- ----------------------------
-- Table structure for s_shop
-- ----------------------------
DROP TABLE IF EXISTS `s_shop`;
CREATE TABLE `s_shop` (
  `shop_id` varchar(30) NOT NULL COMMENT '店铺ID',
  `shop_logo` varchar(1024) NOT NULL COMMENT '店铺logo',
  `store_id` varchar(30) NOT NULL COMMENT '商户ID',
  `shop_name` varchar(128) NOT NULL COMMENT '店铺名称',
  `shop_desc` varchar(512) NOT NULL COMMENT '店铺描述',
  `map_x` varchar(20) NOT NULL DEFAULT '0.0' COMMENT '地区 x坐标',
  `map_y` varchar(20) NOT NULL DEFAULT '0.0' COMMENT '地区 y坐标',
  `send_address` varchar(512) NOT NULL COMMENT '发货地址',
  `return_address` varchar(512) NOT NULL COMMENT '退货地址',
  `return_person` varchar(512) NOT NULL COMMENT '退货联系人',
  `return_link` varchar(11) NOT NULL COMMENT '退货联系电话',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `status_cd` varchar(2) NOT NULL DEFAULT '0' COMMENT '有效标识',
  `state` varchar(12) NOT NULL COMMENT '状态，001 提交 002 审核通过 003 审核不通过',
  `shop_type` varchar(30) NOT NULL COMMENT '店铺类型 ',
  `open_type` varchar(2) NOT NULL COMMENT '开店类型 \r\n1 商家  2 家政 3  全是',
  `area_code` varchar(12) DEFAULT NULL COMMENT '地域编码',
  PRIMARY KEY (`shop_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

