-- ----------------------------
-- Table structure for visit
-- ----------------------------
DROP TABLE IF EXISTS `visit`;
CREATE TABLE `visit` (
  `visit_id` varchar(30) NOT NULL COMMENT '拜访ID',
  `name` varchar(255) NOT NULL COMMENT '姓名',
  `visit_gender` varchar(1) NOT NULL COMMENT '性别',
  `phone_number` varchar(11) NOT NULL COMMENT '电话号码',
  `community_id` varchar(30) DEFAULT NULL COMMENT '小区ID',
  `room_name` varchar(64) NOT NULL COMMENT '拜访房屋',
  `room_id` varchar(64) NOT NULL COMMENT '拜访房屋',
  `owner_id` varchar(30) DEFAULT NULL COMMENT '拜访业主',
  `owner_name` varchar(30) DEFAULT NULL COMMENT '拜访业主',
  `type_id` varchar(30) NOT NULL COMMENT '访客类型',
  `visit_case` varchar(255) DEFAULT NULL COMMENT '拜访事由',
  `visit_time` datetime DEFAULT NULL COMMENT '拜访时间',
  `departure_time` datetime DEFAULT NULL COMMENT '访客离开时间',
  `face_path` varchar(256) DEFAULT NULL COMMENT '访客人脸，类型为人脸时 存人脸',
  `qrcode` varchar(256) DEFAULT NULL COMMENT '访客二维码,类型为访客二维码 存二维码信息',
  `state` varchar(10) NOT NULL COMMENT '审核状态 0表示未审核；1表示审核通过；2表示审核拒绝',
  `msg` varchar(255) DEFAULT NULL COMMENT '审核备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '记录创建时间',
  `status_cd` varchar(2) NOT NULL COMMENT '数据状态，详细参考c_status表，S 保存，0, 在用 1失效',
  `car_num` varchar(12) DEFAULT NULL COMMENT '访客车辆',
  PRIMARY KEY (`visit_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- ----------------------------
-- Table structure for visit_type
-- ----------------------------
DROP TABLE IF EXISTS `visit_type`;
CREATE TABLE `visit_type` (
  `type_id` varchar(30) NOT NULL COMMENT '类型ID',
  `name` varchar(30) NOT NULL COMMENT '类型名称',
  `visit_way` varchar(12) NOT NULL COMMENT '通行方式，FACE 人脸 QRCODE 访客码',
  `audit_way` varchar(12) NOT NULL COMMENT '审核方式，1001 物业审核 2002 业主审核',
  `visit_day` int(11) NOT NULL DEFAULT '1' COMMENT '拜访天数，默认1天',
  `remark` varchar(512) DEFAULT NULL COMMENT '备注',
  `community_id` varchar(30) NOT NULL COMMENT '小区ID',
  `create_time` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `status_cd` varchar(2) NOT NULL DEFAULT '0' COMMENT '数据状态，详细参考t_dict表，0, 在用 1失效',
  PRIMARY KEY (`type_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

